import{_ as t,o as a,c as i,a4 as l}from"./chunks/framework.vNSRaLQv.js";const m=JSON.parse('{"title":"ComfyUI + DirectML + FLUX.2 Klein 失败总结","description":"","frontmatter":{"title":"ComfyUI + DirectML + FLUX.2 Klein 失败总结","date":"2026-07-07T00:00:00.000Z"},"headers":[],"relativePath":"posts/ComfyUI_FLUX_DirectML_失败总结.md","filePath":"posts/ComfyUI_FLUX_DirectML_失败总结.md"}'),o={name:"posts/ComfyUI_FLUX_DirectML_失败总结.md"};function r(d,e,c,n,h,s){return a(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="comfyui-directml-flux-2-klein-失败总结" tabindex="-1">ComfyUI + DirectML + FLUX.2 Klein 失败总结 <a class="header-anchor" href="#comfyui-directml-flux-2-klein-失败总结" aria-label="Permalink to &quot;ComfyUI + DirectML + FLUX.2 Klein 失败总结&quot;">​</a></h1><h2 id="日期" tabindex="-1">日期 <a class="header-anchor" href="#日期" aria-label="Permalink to &quot;日期&quot;">​</a></h2><p>2026-07-07</p><h2 id="硬件环境" tabindex="-1">硬件环境 <a class="header-anchor" href="#硬件环境" aria-label="Permalink to &quot;硬件环境&quot;">​</a></h2><ul><li>GPU: AMD Radeon RX 590 GME (8GB VRAM, Polaris)</li><li>RAM: 16GB</li><li>OS: Windows</li><li>PyTorch: 2.4.1 (CPU) + torch-directml 0.2.5.dev240914</li></ul><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>在 RX 590 上用 ComfyUI 跑 FLUX.2 Klein 9B（GGUF Q4_0 量化）做 txt2img + inpainting。</p><h2 id="遇到过的问题-按顺序" tabindex="-1">遇到过的问题（按顺序） <a class="header-anchor" href="#遇到过的问题-按顺序" aria-label="Permalink to &quot;遇到过的问题（按顺序）&quot;">​</a></h2><h3 id="_1-vram-检测写死-1gb" tabindex="-1">1. VRAM 检测写死 1GB <a class="header-anchor" href="#_1-vram-检测写死-1gb" aria-label="Permalink to &quot;1. VRAM 检测写死 1GB&quot;">​</a></h3><ul><li>位置：<code>comfy/model_management.py</code></li><li><code>get_total_memory()</code> 中对 DirectML 返回 <code>1024 * 1024 * 1024</code>（1GB）</li><li>修复：改为 <code>8192 * 1024 * 1024</code>（匹配 RX 590 的 8GB）</li><li>同样 <code>get_free_memory()</code> 也写死 1GB → 改为 6144MB</li></ul><h3 id="_2-设备选择函数强制-cpu" tabindex="-1">2. 设备选择函数强制 CPU <a class="header-anchor" href="#_2-设备选择函数强制-cpu" aria-label="Permalink to &quot;2. 设备选择函数强制 CPU&quot;">​</a></h3><ul><li><code>unet_inital_load_device()</code> 计算模型解量化后 18GB &gt; 6GB 空闲 → 返回 CPU</li><li><code>text_encoder_device()</code> 在 LOW_VRAM 下返回 CPU</li><li><code>text_encoder_initial_device()</code> 在 LOW_VRAM 下返回 CPU</li><li>修复：对 DirectML 强制返回 GPU 设备</li></ul><h3 id="_3-gpu-上无法解量化-gguf-权重-致命" tabindex="-1">3. GPU 上无法解量化 GGUF 权重（致命） <a class="header-anchor" href="#_3-gpu-上无法解量化-gguf-权重-致命" aria-label="Permalink to &quot;3. GPU 上无法解量化 GGUF 权重（致命）&quot;">​</a></h3><ul><li>位置：<code>ComfyUI-GGUF\\dequant.py</code></li><li>量化权重被送到 DirectML GPU 后，<code>tensor.data</code> 返回 OpaqueTensorImpl</li><li>解量化函数需要 <code>.view(torch.float16)</code>、位运算等操作</li><li>DirectML 不支持这些底层张量访问，抛 <code>Cannot access storage of OpaqueTensorImpl</code></li><li>尝试修复：将量化权重拉回 CPU 解量化再送 GPU 做 forward</li><li>效果：GPU↔CPU 每层往返，实际推理全卡在 CPU，GPU 闲置</li></ul><h2 id="根本原因" tabindex="-1">根本原因 <a class="header-anchor" href="#根本原因" aria-label="Permalink to &quot;根本原因&quot;">​</a></h2><p><strong>torch-directml 年久失修 + GGUF 量化格式不兼容 = 死路</strong></p><ol><li><strong>torch-directml</strong>：最后更新 2024 年，只支持标准 PyTorch op（matmul、conv 等）</li><li><strong>GGUF 量化解量化</strong>：依赖 <code>.view()</code>、位移、int8 张量操作 → DirectML 不支持</li><li><strong>ComfyUI 模型管理</strong>：深度绑定 CUDA memory stats，DirectML 全靠 TODO/hardcode</li><li><strong>解决方案对比</strong>：<table tabindex="0"><thead><tr><th>方案</th><th>GPU 加速</th><th>Inpainting</th><th>可行性</th></tr></thead><tbody><tr><td>ComfyUI + DirectML</td><td>✗</td><td>✓</td><td>已死</td></tr><tr><td>sd-cli Vulkan</td><td>✓</td><td>弱（--mask 有 bug）</td><td>可行</td></tr><tr><td>ROCm/ZLUDA（CUDA 桥接）</td><td>✓</td><td>✓</td><td>RX 590 支持待确认</td></tr></tbody></table></li></ol><h2 id="保留的模型和文件-未动" tabindex="-1">保留的模型和文件（未动） <a class="header-anchor" href="#保留的模型和文件-未动" aria-label="Permalink to &quot;保留的模型和文件（未动）&quot;">​</a></h2><ul><li><code>D:\\files\\FLUX.2\\</code> 下的所有 GGUF 和 safetensors 文件</li></ul><h2 id="经验" tabindex="-1">经验 <a class="header-anchor" href="#经验" aria-label="Permalink to &quot;经验&quot;">​</a></h2><ul><li>DirectML + GGUF = 不兼容，量化格式的底层位操作在 DirectML 上跑不了</li><li>8GB VRAM 跑 Flux 9B 可行的唯一原因是 Q4_0 量化，但量化带来了算子兼容性问题</li><li>ComfyUI 对 DirectML 的支持停留在&quot;能启动&quot;级别，VRAM 检测全是 hardcode</li><li>正确的硬件方案：要么 ROCm/ZLUDA 让 GPU 伪装成 CUDA，要么 sd-cli Vulkan 用内置的 Vulkan 算子</li></ul>',21)])])}const _=t(o,[["render",r]]);export{m as __pageData,_ as default};
